"""Build indexable pages from the exact starter templates exported by Ripot."""
import html, json
from pathlib import Path
from xml.etree import ElementTree as ET
ROOT = Path(__file__).resolve().parents[2]
PUBLIC = ROOT / 'landing/y'
CATALOG = [
 ('colonoscopy-report-template', 'Colonoscopy report template', 'Endoscopy', 'Record bowel preparation, segmental findings, interventions and impressions in a reusable colonoscopy report.'),
 ('upper-gi-endoscopy-report-template', 'Upper GI endoscopy report template', 'Endoscopy', 'An OGD / EGD reporting structure covering indication, sedation, anatomical findings, interventions and impression.'),
 ('abdominal-ultrasound-report-template', 'Abdominal ultrasound report template', 'Ultrasound', 'A reusable abdominopelvic ultrasound structure for organ findings, measurements and impression.'),
 ('echocardiogram-report-template', 'Echocardiogram report template', 'Cardiology', 'A 2D echocardiography reporting structure for chamber measurements, function, valve findings and impression.'),
]
SEO = {
 'colonoscopy-report-template': ('Colonoscopy Report Template – Findings, Bowel Prep & PDF', 'Preview a structured colonoscopy report template with bowel preparation, segmental findings and interventions. Copy a blank outline or open it in Ripot Web.'),
 'upper-gi-endoscopy-report-template': ('Upper GI Endoscopy Report Template – OGD / EGD & PDF', 'Explore an upper GI endoscopy (OGD / EGD) reporting template with oesophagus, stomach, duodenum and intervention sections. Open it in Ripot Web.'),
 'abdominal-ultrasound-report-template': ('Abdominal Ultrasound Report Template – Organs & Measurements', 'Use a structured abdominal ultrasound report template for liver, gallbladder, kidneys and other organs. Preview fields and open it in Ripot Web.'),
 'echocardiogram-report-template': ('Echocardiogram Report Template – 2D Echo Measurements & PDF', 'Preview a 2D echocardiogram report template with chamber measurements, LVEF, Doppler and valve findings. Open the structured editor in Ripot Web.'),
}
e = html.escape
CSS = '''*{box-sizing:border-box}body{margin:0;background:#f6f9f8;color:#153b36;font:16px/1.65 system-ui,sans-serif}a{color:#006d62}a:focus-visible,button:focus-visible{outline:3px solid #dc9e23;outline-offset:4px}header,main,footer{max-width:1120px;margin:auto;padding:24px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d9e6e0}.brand{display:flex;align-items:center;gap:10px;font-size:24px;font-weight:750;text-decoration:none}.brand img{width:48px;height:48px}nav{display:flex;gap:20px;flex-wrap:wrap}h1{font-size:clamp(32px,5vw,54px);line-height:1.1;letter-spacing:-.035em;max-width:850px}h2{font-size:26px;line-height:1.25}h3{font-size:18px}p{max-width:75ch}.eyebrow{color:#59736d;font-size:13px;text-transform:uppercase;letter-spacing:.1em}.lead{font-size:20px;color:#48675f}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0}.button,button{display:inline-block;background:#00695e;color:white;padding:12px 18px;border:0;border-radius:9px;text-decoration:none;font:inherit;font-weight:650;cursor:pointer}.secondary{background:white;color:#00695e;border:1px solid #a8c4bb}.split{display:grid;grid-template-columns:1.15fr 1fr;gap:36px;margin:40px 0}.paper{padding:30px;background:white;border:1px solid #d9e6e0;box-shadow:0 8px 26px #173c3510;border-radius:4px}.paper h3{border-bottom:1px solid #d9e6e0;padding-bottom:12px}.paper li{margin-bottom:10px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:30px 0}.card{background:white;padding:24px;border:1px solid #d9e6e0;border-radius:14px}.card h2{font-size:23px}.note{font-size:14px;color:#586b65}.fields{columns:2;column-gap:32px}.fields li{break-inside:avoid;margin-bottom:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:15px/1.7 system-ui;background:#edf4f0;padding:22px;border-radius:12px}footer{border-top:1px solid #d9e6e0;margin-top:40px}section{scroll-margin-top:20px}@media(max-width:700px){header,main,footer{padding:20px}.split,.cards{grid-template-columns:1fr}.fields{columns:1}.paper{padding:20px}header{align-items:flex-start;gap:16px}nav{gap:10px;font-size:14px}.button{width:100%;text-align:center}}@media print{header,footer,.actions,.note,button,nav{display:none}body{background:white}.split{display:block}.paper{box-shadow:none;border:0}.split>aside{display:none}}'''
SCRIPT = '''document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{const text=b.dataset.copy==='url'?location.href:document.getElementById('outline').textContent;try{await navigator.clipboard.writeText(text);b.textContent='Copied';}catch{b.textContent='Select the text or copy the page address';}}));'''
def shell(title,desc,path,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Ripot</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="https://ripot.app{path}"><link rel="icon" href="/images/ripot-icon.png"><link rel="stylesheet" href="/templates/templates.css"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="https://ripot.app{path}"></head><body><header><a class="brand" href="/"><img src="/images/ripot-icon.png" alt="">Ripot</a><nav aria-label="Main"><a href="/templates/">Templates</a><a href="/#download">Get Ripot</a><a href="/contact.html">Support</a></nav></header><main>{body}</main><footer><p>Ripot · Smarter Clinical Reporting</p><nav><a href="mailto:support@ripot.app">support@ripot.app</a><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a><a href="https://www.linkedin.com/company/ripot-technology/" target="_blank" rel="noopener noreferrer">Follow Ripot on LinkedIn</a></nav><p class="note">A documentation tool, not a substitute for clinical judgement.</p></footer><script src="/templates/templates.js" defer></script></body></html>'''
def walk(nodes,depth=0):
 for n in nodes:
  if n.get('type')=='section':
   yield (n.get('title',''),depth,n.get('unit',''))
   yield from walk(n.get('children',[]),depth+1)
def card(item):
 slug,title,specialty,desc=item
 return f'<article class="card"><span class="eyebrow">{e(specialty)}</span><h2><a href="/templates/{slug}/">{e(title)}</a></h2><p>{e(desc)}</p><p class="note">Contributor: Ripot · Starter template</p><a href="/templates/{slug}/">Preview and use →</a></article>'
def main():
 out=PUBLIC/'templates';out.mkdir(exist_ok=True)
 (out/'templates.css').write_text(CSS)
 (out/'templates.js').write_text(SCRIPT)
 (out/'index.html').write_text(shell('Clinical report templates','Browse reusable endoscopy, ultrasound and echocardiography report structures. Preview, download or open a template in Ripot.','/templates/', '<span class="eyebrow">The Ripot template library</span><h1>A clear starting point for your next report.</h1><p class="lead">Choose a specialty, explore the fields and make the report your own.</p><p>Open a template in the browser, or download its structure for import into Ripot. Start with blank findings and record what you actually observed.</p><div class="cards">'+''.join(map(card,CATALOG))+'</div><section class="card"><h2>Have a useful reporting structure?</h2><p>Contact <a href="mailto:support@ripot.app">support@ripot.app</a> to discuss contributing a patient-free template. Include its specialty and how you would like to be credited. Contributions are reviewed before publication.</p></section>'))
 for item in CATALOG:
  slug,title,specialty,desc=item
  payload=json.loads((out/'downloads'/f'{slug}.ripottemplate.json').read_text())
  template=payload['template'];fields=list(walk(template['roots']))
  outline='Patient name: [enter]\nPatient identifier: [enter]\nReport date: [enter]\n'+'\n'.join('  '*depth+label+(' ('+unit+')' if unit else '')+': [enter]' for label,depth,unit in fields)+'\nImpression: [enter]\nSigned by: [enter]'
  top=[label for label,depth,unit in fields if depth==0]
  body=f'''<span class="eyebrow">{e(specialty)} · Contributor: Ripot</span><h1>{e(title)}</h1><p class="lead">{e(desc)}</p><div class="actions"><a class="button" href="https://ripot-web.web.app/?template={slug}&amp;utm_source=ripot_templates&amp;utm_medium=organic_landing&amp;utm_campaign={slug}">Use this template in Ripot Web →</a><a class="button secondary" href="/templates/downloads/{slug}.ripottemplate.json" download>Download Ripot template</a><button class="secondary" data-copy="url">Copy template link</button></div><p class="note">Open in your browser, or import the downloaded file from Templates → Import. Built-in reporting is available free; Premium features and plan limits are shown in the app.</p><div class="split"><section class="paper" aria-label="Blank report structure preview"><span class="eyebrow">Structure preview · No patient data</span><h2>{e(template['name'])}</h2><p>Patient: ____________________<br>Identifier: __________________<br>Date: ______________________</p><h3>Report sections</h3><ol>{''.join('<li>'+e(t)+'</li>' for t in top)}</ol><p>Clinician: __________________<br>Signature: _________________</p></section><aside><h2>Spend your time on findings.</h2><p>Use this structure in Ripot, adapt the fields to your workflow, add images and review the PDF before sharing.</p><h3>Reusable structure</h3><p>Opening the template starts a new report. It does not change your saved reports or overwrite your own templates.</p><h3>Your clinical data stays local</h3><p>Report content stays on your device or browser. Keep a separate backup and choose appropriate destinations when exporting.</p><a href="/#download">Get Ripot for Android or Windows →</a></aside></div><section><h2>Included fields</h2><ul class="fields">{''.join('<li>'+e(label)+(' · '+e(unit) if unit else '')+'</li>' for label,depth,unit in fields)}</ul></section><section><h2>Copy the blank report outline</h2><p>A reusable starting point, without prefilled normal findings. Complete and check each section for the examination performed.</p><button data-copy="outline">Copy report outline</button><pre id="outline">{e(outline)}</pre></section><section><h2>Explore other templates</h2><div class="cards">{''.join(card(i) for i in CATALOG if i!=item)}</div></section>'''
  dest=out/slug;dest.mkdir(exist_ok=True)
  (dest/'index.html').write_text(shell(seo_title,seo_desc,'/templates/'+slug+'/',body))
 sitemap=PUBLIC/'sitemap.xml';ns='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',ns);tree=ET.parse(sitemap);root=tree.getroot()
 existing={u.find('{'+ns+'}loc').text for u in root}
 for path in ['/templates/']+['/templates/'+i[0]+'/' for i in CATALOG]:
  if 'https://ripot.app'+path not in existing:
   entry=ET.SubElement(root,'{'+ns+'}url');ET.SubElement(entry,'{'+ns+'}loc').text='https://ripot.app'+path
   ET.SubElement(entry,'{'+ns+'}lastmod').text='2026-10-21'
 tree.write(sitemap,encoding='utf-8',xml_declaration=True)
 print('Built hub and four template pages from app exports.')
if __name__=='__main__':main()
